import React, { useState } from 'react';
import { createMachine } from '../services/api';

export default function NewMachineCreate({ onCreated, onCancel }) {
  const [serial, setSerial] = useState('');
  const [model, setModel] = useState('');
  const [customer, setCustomer] = useState(''); // можно вводить ID клиента
  const [serviceCompany, setServiceCompany] = useState(''); // ID сервисной компании
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    const payload = {
      serial_number_machine: serial,
      model_machine: model,
      customer: customer || null,
      service_company: serviceCompany || null,
    };
    try {
      const res = await createMachine(payload);
      setLoading(false);
      onCreated?.(res);
    } catch (err) {
      setLoading(false);
      setError(err?.message || 'Ошибка при создании');
    }
  };

  return (
    <div className="new-machine-create" style={{ border: '1px solid #ccc', padding: 16, borderRadius: 6, margin: '12px 0' }}>
      <h3>Создать новую машину</h3>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <input placeholder="Серийный номер" value={serial} onChange={(e) => setSerial(e.target.value)} required />
        <input placeholder="Модель машины" value={model} onChange={(e) => setModel(e.target.value)} required />
        <input placeholder="Customer (id)" value={customer} onChange={(e) => setCustomer(e.target.value)} />
        <input placeholder="ServiceCompany (id)" value={serviceCompany} onChange={(e) => setServiceCompany(e.target.value)} />
        <div style={{ display: 'flex', gap: 8 }}>
          <button type="submit" disabled={loading}>{loading ? 'Создание...' : 'Создать'}</button>
          <button type="button" onClick={onCancel} disabled={loading}>Отмена</button>
        </div>
        {error && <div style={{ color: 'red' }}>{error}</div>}
      </form>
    </div>
  );
}
